var panes = root.querySelectorAll('[data-pane]');
var nodes = root.querySelectorAll('[data-go]');
var fill = root.querySelector('[data-fill]');
var rail = root.querySelector('[data-rail]');
var count = root.querySelector('[data-count]');
var prev = root.querySelector('[data-prev]');
var next = root.querySelector('[data-next]');
var foot = root.querySelector('[data-foot]');
var last = 2, i = 0, seen = 0;

function render(){
  if (i > seen) seen = i;
  panes.forEach(function(p, k){ p.classList.toggle('is-on', k === i); });
  nodes.forEach(function(b, k){
    b.classList.toggle('is-on', k === i);
    b.classList.toggle('is-done', k < i);
    b.disabled = k > seen;
    if (k === i) { b.setAttribute('aria-current', 'step'); } else { b.removeAttribute('aria-current'); }
  });
  fill.style.width = (i >= last ? 100 : (i / last) * 100) + '%';
  rail.setAttribute('aria-valuenow', String(Math.min(i + 1, 3)));
  count.textContent = i > last ? 'All done' : 'Step ' + (i + 1) + ' of 3';
  prev.disabled = i === 0;
  next.textContent = i === last ? 'Finish setup' : 'Continue';
  foot.style.display = i > last ? 'none' : 'flex';
}

next.addEventListener('click', function(){ i = Math.min(i + 1, last + 1); render(); });
prev.addEventListener('click', function(){ i = Math.max(i - 1, 0); render(); });
nodes.forEach(function(b, k){ b.addEventListener('click', function(){ i = k; render(); }); });

var opts = root.querySelectorAll('[data-opt]');
opts.forEach(function(o){
  o.addEventListener('click', function(){
    opts.forEach(function(x){ x.setAttribute('aria-checked', x === o ? 'true' : 'false'); });
  });
});

var restart = root.querySelector('[data-restart]');
if (restart) restart.addEventListener('click', function(){ i = 0; seen = 0; render(); });
render();

