var items = root.querySelectorAll('[data-item]');
var bar = root.querySelector('[data-bar]');
var pct = root.querySelector('[data-pct]');
var sub = root.querySelector('[data-sub]');
var banner = root.querySelector('[data-banner]');

function update(){
  var done = 0;
  items.forEach(function(b){ if (b.getAttribute('aria-pressed') === 'true') done++; });
  var total = items.length;
  var p = Math.round(done / total * 100);
  bar.style.width = p + '%';
  pct.textContent = p + '%';
  var mins = (total - done) * 2;
  sub.textContent = done + ' of ' + total + ' done' + (mins ? ' · about ' + mins + ' min left' : ' · nothing left to do');
  banner.hidden = done !== total;
}

items.forEach(function(b){
  b.addEventListener('click', function(){
    var on = b.getAttribute('aria-pressed') === 'true';
    b.setAttribute('aria-pressed', on ? 'false' : 'true');
    b.classList.toggle('is-done', !on);
    update();
  });
});

update();

