var steps = [
  {t: 'Filter any view', b: 'Narrow a board to just your work, then save the result as a preset the whole team can reuse.'},
  {t: 'Automate the busywork', b: 'Move a card to Done and a rule can notify the reviewer for you.'},
  {t: 'Share a read-only link', b: 'Anyone with the link sees the live board. No extra seat required.'}
];
var targets = root.querySelectorAll('[data-t]');
var dots = root.querySelectorAll('[data-dot]');
var pop = root.querySelector('[data-pop]');
var arrow = root.querySelector('[data-arrow]');
var title = root.querySelector('[data-title]');
var body = root.querySelector('[data-body]');
var idx = root.querySelector('[data-step]');
var next = root.querySelector('[data-next]');
var skip = root.querySelector('[data-skip]');
var replay = root.querySelector('[data-replay]');
var i = 0;

function place(){
  var pr = pop.getBoundingClientRect();
  var r = targets[i].getBoundingClientRect();
  if (!pr.width || !r.width) return;
  var x = r.left + r.width / 2 - pr.left;
  arrow.style.left = Math.max(16, Math.min(pr.width - 16, x)) + 'px';
}

function render(){
  targets.forEach(function(el, k){ el.classList.toggle('is-on', k === i); });
  dots.forEach(function(d, k){ d.classList.toggle('is-on', k === i); });
  title.textContent = steps[i].t;
  body.textContent = steps[i].b;
  idx.textContent = (i + 1) + ' / ' + steps.length;
  next.textContent = i === steps.length - 1 ? 'Got it' : 'Next';
  place();
}

next.addEventListener('click', function(){
  if (i === steps.length - 1) { root.classList.add('is-done'); replay.focus(); return; }
  i++;
  render();
});
skip.addEventListener('click', function(){ root.classList.add('is-done'); });
replay.addEventListener('click', function(){ i = 0; root.classList.remove('is-done'); render(); next.focus(); });
render();

