var ring = root.querySelector('[data-ring]');
var num = root.querySelector('[data-num]');
var label = root.querySelector('[data-label]');
var btn = root.querySelector('[data-next]');
var rows = root.querySelectorAll('[data-row]');
var total = rows.length;
var done = 2;
var shown = 0, target = 0, raf = 0, settle = 0;
var still = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;

function paint(){
  ring.style.setProperty('--mdo-setup-ring-p', shown.toFixed(1) + '%');
  num.textContent = Math.round(shown) + '%';
  ring.setAttribute('aria-label', 'Setup progress ' + Math.round(shown) + ' percent');
}

function tick(){
  if (!root.isConnected) { raf = 0; return; }
  var d = target - shown;
  if (Math.abs(d) < 0.4) { shown = target; paint(); raf = 0; return; }
  shown += d * 0.16;
  paint();
  raf = requestAnimationFrame(tick);
}

function sync(){
  rows.forEach(function(r, k){
    r.classList.toggle('is-done', k < done);
    r.classList.toggle('is-now', k === done);
  });
  label.textContent = done >= total ? 'All 4 steps complete' : done + ' of ' + total + ' steps complete';
  btn.textContent = done >= total ? 'Go to your dashboard' : 'Next: ' + rows[done].getAttribute('data-row');
  btn.classList.toggle('is-complete', done >= total);
  target = done / total * 100;
  if (still) { shown = target; paint(); return; }
  if (!raf) raf = requestAnimationFrame(tick);
  // frames are not delivered while the view is hidden, so land the value anyway
  clearTimeout(settle);
  settle = setTimeout(function(){
    if (!root.isConnected) return;
    if (Math.abs(target - shown) > 0.5) { shown = target; paint(); }
  }, 700);
}

btn.addEventListener('click', function(){
  if (done < total) { done++; sync(); }
});

sync();

