var cta = root.querySelector('[data-create]');
var again = root.querySelector('[data-again]');
var made = root.querySelector('[data-made]');
var pick = 'Blank canvas';

chips.forEach(function(c){
  c.addEventListener('click', function(){
    pick = c.getAttribute('data-chip');
    chips.forEach(function(x){
      var on = x === c;
      x.classList.toggle('is-on', on);
      x.setAttribute('aria-checked', on ? 'true' : 'false');
    });
    cta.textContent = c.getAttribute('data-cta');
  });
});

cta.addEventListener('click', function(){
  made.textContent = pick + ' · 1 member · just now';
  root.classList.add('is-made');
  again.focus();
});

again.addEventListener('click', function(){
  root.classList.remove('is-made');
  cta.focus();
});

