.mdo-plan-picker__price b{font:650 14px ui-monospace,Menlo,monospace;color:#EDFBF1;font-variant-numeric:tabular-nums}
.mdo-plan-picker__price b.is-swap{animation:mdo-plan-picker-swap .3s ease}
.mdo-plan-picker__price i{font:400 9.5px system-ui,-apple-system,"Segoe UI",Roboto,sans-serif;font-style:normal;color:#5F7268}
.mdo-plan-picker__plan[data-plan="Starter"] .mdo-plan-picker__price i{display:none}
.mdo-plan-picker__note{margin:10px 0 11px;font-size:10.5px;color:#6F8479}
.mdo-plan-picker__cta{width:100%;padding:10px 12px;border-radius:10px;font:650 12px system-ui,-apple-system,"Segoe UI",Roboto,sans-serif;color:#062012;background:linear-gradient(180deg,#7CEFA6,#3FCB79);border:0;cursor:pointer;transition:filter .18s,transform .1s}
.mdo-plan-picker__cta:hover{filter:brightness(1.06)}
.mdo-plan-picker__cta:active{transform:translateY(1px)}
.mdo-plan-picker__cta:focus-visible{outline:2px solid #BEF5D2;outline-offset:3px}
@keyframes mdo-plan-picker-swap{from{opacity:0;transform:translateY(-4px)}to{opacity:1;transform:none}}
@media (prefers-reduced-motion: reduce){
  .mdo-plan-picker__knob{transition:none}
  .mdo-plan-picker__price b.is-swap{animation:none}
  .mdo-plan-picker__cta{transition:none}
  .mdo-plan-picker__cta:active{transform:none}
}

