var bills = root.querySelectorAll('[data-bill]');
var plans = root.querySelectorAll('[data-plan]');
var note = root.querySelector('[data-note]');
var cta = root.querySelector('[data-cta]');
var price = { mo: [0, 18, 39], yr: [0, 14, 31] };
var annual = false, pick = 1, first = true;

function render(){
  var col = annual ? price.yr : price.mo;
  plans.forEach(function(p, k){
    p.setAttribute('aria-checked', k === pick ? 'true' : 'false');
    var amt = p.querySelector('[data-amt]');
    var text = col[k] === 0 ? 'Free' : '$' + col[k];
    if (amt.textContent !== text) {
      amt.textContent = text;
      if (!first) { amt.classList.remove('is-swap'); void amt.offsetWidth; amt.classList.add('is-swap'); }
    }
  });
  bills.forEach(function(b){
    var on = (b.getAttribute('data-bill') === 'yr') === annual;
    b.classList.toggle('is-on', on);
    b.setAttribute('aria-pressed', on ? 'true' : 'false');
  });
  root.classList.toggle('is-annual', annual);
  note.textContent = annual ? 'Billed once a year · two months free.' : 'Switch to annual billing to save 20%.';
  var name = plans[pick].getAttribute('data-plan');
  cta.textContent = col[pick] === 0 ? 'Continue with ' + name : 'Continue with ' + name + ' · $' + col[pick] + '/mo';
  first = false;
}

bills.forEach(function(b){
  b.addEventListener('click', function(){
    annual = b.getAttribute('data-bill') === 'yr';
    render();
  });
});

plans.forEach(function(p, k){
  p.addEventListener('click', function(){ pick = k; render(); });
});

render();
